#include <bits/stdc++.h>using namespace std; const int N = 1e6;vector<bool> isPrime(N + 1, true); void sieve(){         isPrime[0] = isPrime[1] = false;         for (int i = 2; i * i <= N; i++)         {                  if (isPrime[i])                  {                           for (int j = i * i; j <= N; j += i)                                    isPrime[j] = false;                  }         }} int main(){          sieve();          int n;         cin >> n;         while (n--)         {                  long long x;                  cin >> x;                   long long r = sqrt(x);                  if (r * r == x && isPrime[r])                           cout << "YES\n";                  else                           cout << "NO\n";         }         return 0;}